def validate_train_cover(s, fast=False):
    # s like "k=50,d=8,steps=40,split=100,shrink" or "k=50,d=8,f=20,..." for fast
    # Returns True if valid, False if invalid (to trigger Incorrect)
    # Observed: "k" alone invalid, "k=50" valid, "k=50,d=8" valid, empty invalid (handled before), "k=abc" invalid? Probably Incorrect (non-numeric)
    # Keys: for cover: k,d,steps,split,shrink ; for fastcover: k,d,f,steps,split,accel,shrink
    # shrink may be alone or shrink=#? Help: shrink[=#] means shrink or shrink=#?
    # How to validate numeric? Must be digits only? No suffix? Probably digits.
    # Also need to handle "shrink=5"? Valid.
    if s is None or s == "":
        return False
    allowed_cover = {"k", "d", "steps", "split", "shrink"}
    allowed_fast = {"k", "d", "f", "steps", "split", "accel", "shrink"}
    allowed = allowed_fast if fast else allowed_cover
    parts = s.split(",")
    for p in parts:
        p = p.strip()
        if p == "":
            return False
        if "=" in p:
            k, v = p.split("=", 1)
            k = k.strip()
            v = v.strip()
            if k not in allowed:
                return False
            if k == "shrink":
                # shrink with = must have numeric? shrink= with empty? Probably invalid? Let's require numeric if = present
                if v == "":
                    return False
                if not re.fullmatch(r'\d+', v):
                    return False
            else:
                if v == "" or not re.fullmatch(r'\d+', v):
                    return False
        else:
            # No =, must be "shrink" alone
            if p != "shrink":
                return False
            if "shrink" not in allowed:
                return False
    return True

